package com.classpulse.backend.model;

import jakarta.persistence.*;
import lombok.*;

import java.time.Instant;
import java.util.UUID;

/**
 * JPA entity representing a registered user account in the ClassPulse platform.
 * <p>
 * Supports both instructors (TEACHER) who manage sessions and students who authenticate
 * for persistent tracking and historical participation.
 */
@Entity
@Table(name = "users")
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class User {

    /**
     * Unique surrogate primary key UUID generated by the application on registration.
     */
    @Id
    @Column(columnDefinition = "uuid", updatable = false, nullable = false)
    private UUID id;

    /**
     * Unique email address used as the primary login identifier.
     */
    @Column(nullable = false, unique = true)
    private String email;

    /**
     * Cryptographic hash of the user's password generated using BCrypt.
     * Raw passwords are never persisted.
     */
    @Column(name = "password_hash", nullable = false)
    private String passwordHash;

    /**
     * Full real name or display name of the user.
     */
    @Column(name = "full_name", nullable = false)
    private String fullName;

    /**
     * Authorization role of the user (TEACHER or STUDENT).
     */
    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 50)
    private UserRole role;

    /**
     * UTC timestamp when this user account was created.
     */
    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    /**
     * UTC timestamp when this user account was last modified.
     */
    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;
}
